// Regression: prices with thousands separators (e.g. "2,450.50", seen in production
// logs) made parseAmount dereference a null match and POST /checkout return 500.
const assert = require('assert');
const { parseAmount } = require('../src/money');
const { handle } = require('../src/server');

test('parses amounts with thousands separators', () => {
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('1,005.99'), 100599);
  assert.strictEqual(parseAmount('1,000,000'), 100000000);
});

test('rejects malformed amounts with a descriptive error', () => {
  for (const bad of ['', 'abc', '1,23', '12,3456.00', '1.234', ',100']) {
    assert.throws(() => parseAmount(bad), /^Error: Invalid amount: /, `input ${JSON.stringify(bad)}`);
  }
});

test('POST /checkout succeeds for comma-formatted prices', () => {
  const origLog = console.log;
  console.log = () => {};
  let res;
  try {
    res = handle({ method: 'POST', path: '/checkout', body: { id: 'ord_10135', items: [{ sku: 'P-79', price: '2,450.50', qty: 2 }] } });
  } finally {
    console.log = origLog;
  }
  assert.strictEqual(res.status, 200);
  assert.deepStrictEqual(res.body, { orderId: 'ord_10135', totalCents: 490100 });
});

